import React from "react";
import { useProductView } from "./useProductView";
import {
  Row,
  Col,
  Card,
  Label,
  Input,
  Button,
  CardImg,
  CardText,
  CardBody,
  CardTitle,
  FormGroup,
  CardSubtitle,
} from "reactstrap";

const ProductView = () => {
  const {
    product,
    getImage,
    selectedColor,
    selectedSize,
    selectedQuantity,
    setSelectedColor,
    setSelectedSize,
    handleQuantityChange,
  } = useProductView();

  if (!product || !product.name) {
    return null;
  }

  const quantityOptions = Array.from(Array(Number(product.quantity)).keys()).map(
    (num) => num + 1
  );

  return (
    <Card className="product-details">
      <Row>
        <Col sm="12" md="4">
          <CardImg
            left="true"
            width="100%"
            src={`http://localhost:1337${getImage(selectedColor)}`}
            alt=""
          />
        </Col>
        <Col sm="12" md="8">
          <CardBody>
            <CardTitle>{product.name}</CardTitle>
            <CardText>{product.description}</CardText>
            <CardSubtitle>
              <strong>Price: £{product.price}</strong>
            </CardSubtitle>
            <CardSubtitle>{product.quantity} items Left</CardSubtitle>
            <div>
              <CardSubtitle>Sizes:</CardSubtitle>
              <div className="sizes">
                {product.sizes.map((size) => (
                  <span
                    key={size.name}
                    className={`${selectedSize === size.name ? "active" : ""}`}
                    onClick={() => setSelectedSize(size.name)}
                  >
                    {size.name}
                  </span>
                ))}
              </div>
            </div>
            <div>
              <CardSubtitle>Selected color: {selectedColor}</CardSubtitle>
              <div className="colors">
                {product.colors.map((color) => (
                  <span
                    key={color.name}
                    className={`${selectedColor === color.name ? "active" : ""}`}
                    onClick={() => setSelectedColor(color.name)}
                  >
                    <img
                      src={`http://localhost:1337${getImage(color.name)}`}
                      alt={color.name}
                    />
                  </span>
                ))}
              </div>
              <FormGroup className="quantity">
                <Label for="quantitySelect">Quantity</Label>
                <Input
                  value={selectedQuantity}
                  type="select"
                  name="quantity"
                  id="quantitySelect"
                  onChange={handleQuantityChange}
                >
                  {quantityOptions.map((number) => (
                    <option key={number} value={number}>
                      {number}
                    </option>
                  ))}
                </Input>
              </FormGroup>
            </div>
            <Button color="primary">Add to basket</Button>
          </CardBody>
        </Col>
      </Row>
    </Card>
  );
};

export default ProductView;
